<?php
/** GitHub Copilot: completions in the editor, chat, agent mode and the coding agent, instructions and good practice. */

return [
    'id' => 'github-copilot', 'family' => 'assistants', 'after' => null,
    'title' => L('GitHub Copilot', 'GitHub Copilot'), 'short' => L('GitHub Copilot', 'GitHub Copilot'), 'level' => L('Base', 'Basics'),
    'desc' => L('Programmare con l’assistente di GitHub: suggerimenti nell’editor, chat, modalità agente e agente di programmazione, istruzioni del repository e buone pratiche.', 'Programming with GitHub’s assistant: suggestions in the editor, chat, agent mode and the coding agent, repository instructions and good practice.'),
    'lessons' => [
        lesson('completions', L('Suggerimenti nell’editor', 'Suggestions in the editor'), [
            P('**GitHub Copilot** lavora dentro l’editor (VS Code, Visual Studio, JetBrains e altri) e propone il codice mentre scrivi: una riga o una funzione intera, in grigio. **Tab** accetta, **Esc** rifiuta. Funziona meglio se il contesto è chiaro: nomi parlanti, un commento che descrive cosa vuoi, file correlati aperti.', '**GitHub Copilot** works inside the editor (VS Code, Visual Studio, JetBrains and others) and suggests code as you type: a line or a whole function, in grey. **Tab** accepts, **Esc** rejects. It works best when context is clear: telling names, a comment describing what you want, related files open.'),
            C('// Restituisce il prezzo con IVA al 22%, arrotondato a 2 decimali
function prezzoConIva(prezzo) {
  // Copilot propone: return Math.round(prezzo * 1.22 * 100) / 100;
}', 'js'),
            P('C’è un piano gratuito con limiti mensili e piani a pagamento per singoli e aziende. Puoi scegliere tra modelli di diversi fornitori. Un suggerimento è una **proposta**: leggilo come leggeresti il codice di un collega.', 'There is a free plan with monthly limits and paid plans for individuals and companies. You can choose among models from different providers. A suggestion is a **proposal**: read it as you would a colleague’s code.'),
        ], [
            Q('c1', L('Come accetti un suggerimento di Copilot?', 'How do you accept a Copilot suggestion?'), ['Tab', 'Esc', 'Ctrl+Z', 'F5'], 0, L('Esc lo rifiuta.', 'Esc rejects it.')),
            Q('c2', L('Che cosa aiuta Copilot a suggerire meglio?', 'What helps Copilot suggest better?'), [L('Nomi chiari e un commento che descrive l’obiettivo', 'Clear names and a comment describing the goal'), L('Variabili chiamate x1, x2', 'Variables named x1, x2'), L('Chiudere tutti i file', 'Closing all files'), L('Scrivere in maiuscolo', 'Writing in capitals')], 0, L('Il contesto è tutto.', 'Context is everything.')),
            Q('c3', L('Come va trattato un suggerimento?', 'How should a suggestion be treated?'), [L('Come codice da rileggere', 'As code to review'), L('Come sicuramente corretto', 'As surely correct'), L('Come un segreto', 'As a secret'), L('Va sempre rifiutato', 'Always rejected')], 0, L('La responsabilità resta tua.', 'Responsibility stays yours.')),
        ], task('js', L('Scrivi un commento che guidi Copilot a creare la funzione `giorniTra(data1, data2)` che restituisce i giorni interi tra due date, poi la firma della funzione.', 'Write a comment guiding Copilot to create the function `giorniTra(data1, data2)` returning the whole days between two dates, then the function signature.'), '', [re('^\s*//.*(giorni|days)', L('Un commento descrive l’obiettivo', 'A comment describes the goal')), re('function\s+giorniTra\s*\(\s*data1\s*,\s*data2\s*\)', L('La firma della funzione', 'The function signature'))], '', "// Restituisce il numero di giorni interi tra due date\nfunction giorniTra(data1, data2) {"), [
            dMatch(pMatch(), [['Tab', L('Accetta', 'Accepts')], ['Esc', L('Rifiuta', 'Rejects')], [L('Commento', 'Comment'), L('Descrive cosa vuoi', 'Describes what you want')], [L('File aperti', 'Open files'), L('Danno contesto', 'Give context')]], L('Lavorare con i suggerimenti.', 'Working with suggestions.')),
            dFlash(pFlash(), [[L('Copilot funziona dentro VS Code', 'Copilot works inside VS Code'), true], [L('Ogni suggerimento è sicuramente corretto', 'Every suggestion is surely correct'), false], [L('Esiste un piano gratuito con limiti', 'There is a free plan with limits'), true], [L('Copilot funziona meglio con nomi oscuri', 'Copilot works better with obscure names'), false]], L('Un collega veloce, da controllare.', 'A fast colleague, to check.')),
        ]),
        lesson('chat', L('Copilot Chat', 'Copilot Chat'), [
            P('**Copilot Chat** risponde a domande sul codice dentro l’editor: spiegare una funzione, trovare un bug, scrivere test, proporre una modifica. Seleziona il codice e chiedi, oppure usa i comandi rapidi con la barra.', '**Copilot Chat** answers questions about code inside the editor: explaining a function, finding a bug, writing tests, proposing a change. Select the code and ask, or use the slash shortcuts.'),
            C('/explain     spiega il codice selezionato
/fix         propone una correzione
/tests       genera i test
/doc         scrive la documentazione
#file:utils.js   aggiunge un file al contesto
@workspace   domande su tutto il progetto', 'text'),
            P('Più contesto dai, migliori le risposte: indica i file con `#`, descrivi l’errore che vedi (incolla il messaggio) e cosa ti aspettavi. Chiedi spiegazioni, non solo codice: è anche un ottimo modo per imparare.', 'The more context you give, the better the answers: point to files with `#`, describe the error you see (paste the message) and what you expected. Ask for explanations, not just code: it is also a great way to learn.'),
        ], [
            Q('h1', L('Quale comando genera i test?', 'Which command generates tests?'), ['/tests', '/fix', '/explain', '/doc'], 0, L('Poi rileggili ed eseguili.', 'Then review and run them.')),
            Q('h2', L('Come aggiungi un file al contesto della chat?', 'How do you add a file to the chat context?'), ['#file:nome', '@nome', '!nome', '$nome'], 0, L('Il modello lo legge.', 'The model reads it.')),
            Q('h3', L('Che cosa incollare quando chiedi aiuto su un errore?', 'What should you paste when asking for help with an error?'), [L('Il messaggio di errore e cosa ti aspettavi', 'The error message and what you expected'), L('Niente', 'Nothing'), L('La password', 'The password'), L('Tutto il disco', 'The whole disk')], 0, L('Contesto preciso.', 'Precise context.')),
        ], task('text', L('Scrivi una domanda per Copilot Chat che usi `/fix`, citi il file con `#file:carrello.js` e descriva l’errore `TypeError: totale is undefined`.', 'Write a Copilot Chat question using `/fix`, referencing the file with `#file:carrello.js` and describing the error `TypeError: totale is undefined`.'), '', [re('/fix', L('Usi /fix', 'You use /fix')), re('#file:carrello\.js', L('Citi il file', 'You reference the file')), re('TypeError: totale is undefined', L('Incolli l’errore', 'You paste the error'))], '', '/fix #file:carrello.js Quando aggiungo un prodotto ottengo "TypeError: totale is undefined". Mi aspetto che il totale si aggiorni.'), [
            dMatch(pMatch(), [['/explain', L('Spiega il codice', 'Explains code')], ['/fix', L('Propone una correzione', 'Proposes a fix')], ['/tests', L('Genera test', 'Generates tests')], ['#file', L('Aggiunge un file', 'Adds a file')], ['@workspace', L('Tutto il progetto', 'The whole project')]], L('I comandi della chat.', 'Chat commands.')),
            dFlash(pFlash(), [[L('Copilot Chat può spiegare il codice selezionato', 'Copilot Chat can explain selected code'), true], [L('Più contesto peggiora le risposte', 'More context worsens answers'), false], [L('Si possono generare test con /tests', 'Tests can be generated with /tests'), true], [L('La chat non vede mai i file del progetto', 'The chat never sees project files'), false]], L('Chiedere bene.', 'Asking well.')),
        ]),
        lesson('agent', L('Modalità agente e agente di programmazione', 'Agent mode and the coding agent'), [
            P('In **modalità agente** Copilot non si limita a suggerire: pianifica, modifica più file, esegue comandi e test nel terminale e corregge finché il compito è fatto, chiedendo conferma per le azioni. Tu rivedi il diff e decidi cosa tenere.', 'In **agent mode** Copilot does not just suggest: it plans, edits several files, runs commands and tests in the terminal and iterates until the task is done, asking confirmation for actions. You review the diff and decide what to keep.'),
            P('L’**agente di programmazione** di GitHub lavora invece in autonomia nel cloud: gli assegni una issue, lui crea un branch, scrive il codice e apre una **pull request** da rivedere. Le modifiche passano comunque dalla revisione umana e dai test automatici prima del merge.', 'GitHub’s **coding agent** instead works autonomously in the cloud: you assign it an issue, it creates a branch, writes the code and opens a **pull request** to review. Changes still go through human review and automated tests before merging.'),
            Tip('Issue chiare producono PR migliori: descrivi il comportamento atteso, i file coinvolti e come verificare.', 'Clear issues produce better PRs: describe the expected behaviour, the files involved and how to verify.'),
        ], [
            Q('a1', L('Che cosa fa la modalità agente?', 'What does agent mode do?'), [L('Modifica più file ed esegue comandi fino a finire il compito', 'Edits several files and runs commands until the task is done'), L('Solo completamenti di una riga', 'Only one-line completions'), L('Traduce il codice', 'Translates code'), L('Niente di diverso', 'Nothing different')], 0, L('Chiedendo conferma.', 'Asking confirmation.')),
            Q('a2', L('Che cosa produce l’agente di programmazione di GitHub?', 'What does GitHub’s coding agent produce?'), [L('Una pull request da rivedere', 'A pull request to review'), L('Un merge diretto su main', 'A direct merge to main'), L('Un’email', 'An email'), L('Un nuovo repository', 'A new repository')], 0, L('La revisione resta umana.', 'Review stays human.')),
            Q('a3', L('Come ottieni PR migliori dall’agente?', 'How do you get better PRs from the agent?'), [L('Scrivendo issue chiare con criteri di verifica', 'Writing clear issues with verification criteria'), L('Issue di una parola', 'One-word issues'), L('Niente test', 'No tests'), L('Più agenti insieme sempre', 'Always more agents')], 0, L('Come con un collega nuovo.', 'As with a new colleague.')),
        ], task('text', L('Scrivi il testo di una issue da assegnare all’agente: righe `Obiettivo:`, `File:` e `Verifica:` (con un test da far passare).', 'Write an issue to assign to the agent: lines `Goal:`, `Files:` and `Verify:` (with a test to make pass).'), "Obiettivo: \nFile: \nVerifica: ", [re('^(Obiettivo|Goal):\s*\S.{5,}', L('L’obiettivo', 'The goal')), re('^(File|Files):\s*\S.{3,}', L('I file coinvolti', 'The files involved')), re('^(Verifica|Verify):\s*.*test', L('Come verificare, con un test', 'How to verify, with a test'))], '', "Obiettivo: il carrello deve applicare lo sconto del 10% sopra i 100 euro.\nFile: src/carrello.js, src/carrello.test.js\nVerifica: aggiungi un test con un carrello da 120 euro che restituisce 108 e falli passare tutti."), [
            dOrder(pSort(), [L('Scrivi una issue chiara', 'Write a clear issue'), L('Assegnala all’agente', 'Assign it to the agent'), L('L’agente apre una pull request', 'The agent opens a pull request'), L('Rivedi il codice e i test', 'Review the code and tests'), L('Fai il merge', 'Merge')], L('Dal problema alla soluzione.', 'From problem to solution.')),
            dMatch(pMatch(), [[L('Suggerimenti', 'Suggestions'), L('Righe mentre scrivi', 'Lines as you type')], ['Chat', L('Domande sul codice', 'Questions about code')], [L('Modalità agente', 'Agent mode'), L('Più file e comandi nell’editor', 'Several files and commands in the editor')], [L('Agente di programmazione', 'Coding agent'), L('Issue → pull request nel cloud', 'Issue → pull request in the cloud')]], L('Quattro livelli di aiuto.', 'Four levels of help.')),
        ]),
        lesson('practice', L('Istruzioni e buone pratiche', 'Instructions and good practice'), [
            P('Il file **`.github/copilot-instructions.md`** nel repository dà a Copilot le regole del progetto: linguaggio e versioni, stile, librerie da usare o evitare, come si lanciano i test. Vale per tutti i membri del team.', 'The **`.github/copilot-instructions.md`** file in the repository gives Copilot the project’s rules: language and versions, style, libraries to use or avoid, how to run tests. It applies to the whole team.'),
            C('# Istruzioni per Copilot
- TypeScript strict, niente `any`.
- Test con Vitest: `npm test`.
- Le date si gestiscono con date-fns, non con moment.
- Messaggi all’utente in italiano.', 'markdown'),
            P('Buone pratiche: rileggi sempre il codice generato, fai girare i test, attenzione a segreti e dati personali nel contesto, controlla le licenze se un suggerimento sembra copiato, e nelle aziende rispetta le politiche dell’organizzazione su quali repository e funzioni sono permessi.', 'Good practice: always review generated code, run the tests, beware of secrets and personal data in the context, check licences if a suggestion looks copied, and in companies follow the organisation’s policies on which repositories and features are allowed.'),
        ], [
            Q('p1', L('Dove si scrivono le istruzioni di progetto per Copilot?', 'Where do you write project instructions for Copilot?'), ['.github/copilot-instructions.md', 'README.txt', '.env', 'package.json'], 0, L('Valgono per tutto il team.', 'They apply to the whole team.')),
            Q('p2', L('Che cosa conviene mettere nelle istruzioni?', 'What belongs in the instructions?'), [L('Stile, librerie, come lanciare i test', 'Style, libraries, how to run tests'), L('Le password del database', 'Database passwords'), L('Niente', 'Nothing'), L('La cronologia dei commit', 'Commit history')], 0, L('Le regole del progetto.', 'The project’s rules.')),
            Q('p3', L('Che cosa fare se un suggerimento sembra copiato da un altro progetto?', 'What to do if a suggestion looks copied from another project?'), [L('Controllare licenza e origine', 'Check licence and origin'), L('Accettarlo senza pensarci', 'Accept it without thinking'), L('Pubblicarlo subito', 'Publish it at once'), L('Niente', 'Nothing')], 0, L('Le licenze contano.', 'Licences matter.')),
        ], task('markdown', L('Scrivi un `.github/copilot-instructions.md` con tre regole, una per riga con `-`, tra cui come si lanciano i **test**.', 'Write a `.github/copilot-instructions.md` with three rules, one per line with `-`, including how to run the **tests**.'), "# Istruzioni per Copilot\n- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre regole', 'Three rules')), re('test', L('Come lanciare i test', 'How to run the tests'))], '', "# Istruzioni per Copilot\n- Python 3.12 con type hint ovunque.\n- Test con pytest: `pytest -q`.\n- Niente dipendenze nuove senza chiedere."), [
            dMatch(pMatch(), [['copilot-instructions.md', L('Regole del progetto', 'Project rules')], [L('Test', 'Tests'), L('Verificano il codice generato', 'Verify generated code')], [L('Licenze', 'Licences'), L('Da controllare se il codice sembra copiato', 'Check if code looks copied')], [L('Politiche aziendali', 'Company policies'), L('Cosa è permesso', 'What is allowed')]], L('Usare Copilot con criterio.', 'Using Copilot wisely.')),
            dFlash(pFlash(), [[L('Le istruzioni del repository valgono per tutto il team', 'Repository instructions apply to the whole team'), true], [L('Conviene mettere i segreti nelle istruzioni', 'Secrets belong in the instructions'), false], [L('Il codice generato va testato', 'Generated code must be tested'), true], [L('Le politiche aziendali non contano con Copilot', 'Company policies do not matter with Copilot'), false]], L('Regole chiare, risultati migliori.', 'Clear rules, better results.')),
        ]),
        lesson('review', L('Code review, test e sicurezza', 'Code review, tests and security'), [
            P('Copilot può **rivedere** una pull request e lasciare commenti, scrivere la **descrizione** della PR e proporre **test** per una funzione (in chat: `/tests`). È un secondo paio d’occhi, non un sostituto della revisione di una persona.', 'Copilot can **review** a pull request and leave comments, write the PR **description** and propose **tests** for a function (in chat: `/tests`). It is a second pair of eyes, not a replacement for a human review.'),
            P('Il codice suggerito può contenere **bug o falle**: query costruite concatenando stringhe, segreti scritti nel codice, librerie inventate o vecchie. Prima di accettare: leggi, fai girare i test, controlla che le dipendenze esistano davvero.', 'Suggested code can contain **bugs or flaws**: queries built by concatenating strings, secrets written into the code, made-up or outdated libraries. Before accepting: read it, run the tests, check that dependencies really exist.'),
        ], [
            Q('rv1', L('Che cosa può fare Copilot su una pull request?', 'What can Copilot do on a pull request?'), [L('Rivederla e scriverne la descrizione', 'Review it and write its description'), L('Approvarla al posto del team, sempre', 'Always approve it on the team’s behalf'), L('Cancellarla', 'Delete it'), L('Pubblicarla su npm', 'Publish it to npm')], 0, L('Aiuta, non decide.', 'It helps, it does not decide.')),
            Q('rv2', L('Quale comando chiede dei test in chat?', 'Which command asks for tests in chat?'), ['/tests', '/fix', '/explain', '/doc'], 0, L('Poi li fai girare.', 'Then you run them.')),
            Q('rv3', L('Che cosa controlli prima di accettare un suggerimento?', 'What do you check before accepting a suggestion?'), [L('Logica, test e dipendenze reali', 'Logic, tests and real dependencies'), L('Solo il colore del codice', 'Only the code colours'), L('Niente, è già verificato', 'Nothing, it is already verified'), L('La lunghezza', 'The length')], 0, L('Le librerie inventate esistono.', 'Made-up libraries happen.')),
        ], task('text', L('Scrivi una checklist di 3 righe con `-` per rivedere codice suggerito: una sui test, una sui segreti, una sulle dipendenze.', 'Write a 3-line `-` checklist for reviewing suggested code: one on tests, one on secrets, one on dependencies.'), '', [re('^-.*(test)', L('Parli dei test', 'You mention tests')), re('^-.*(segret|secret|chiav|key|password)', L('Parli dei segreti', 'You mention secrets')), re('^-.*(dipendenz|dependenc|librer|librar|pacchett|package)', L('Parli delle dipendenze', 'You mention dependencies'))], '', "- Faccio girare i test e ne aggiungo per i casi limite\n- Nessun segreto o chiave API scritto nel codice\n- Le dipendenze proposte esistono e sono aggiornate"), [
            dMatch(pMatch(), [['/tests', L('Propone test', 'Proposes tests')], ['/explain', L('Spiega il codice', 'Explains code')], ['/fix', L('Propone una correzione', 'Proposes a fix')], ['Code review', L('Commenti sulla PR', 'Comments on the PR')]], L('Copilot che controlla.', 'Copilot checking.')),
            dFlash(pFlash(), [[L('I suggerimenti possono contenere falle', 'Suggestions can contain flaws'), true], [L('La review di Copilot sostituisce quella umana', 'Copilot’s review replaces the human one'), false], [L('Una libreria suggerita va verificata', 'A suggested library must be checked'), true], [L('I segreti nel codice vanno bene se è privato', 'Secrets in code are fine if it is private'), false]], L('Fidarsi, ma verificare.', 'Trust, but verify.')),
        ]),
    ],
